const items = $input.all();

const core = items.find(item => item.json.type === 'core')?.json.prompt ?? '';
const evaluator = items.find(item => item.json.type === 'evaluator')?.json.prompt ?? '';

return [{ json: { prompt: core, evaluator: evaluator } }];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
let returnValue =  { data: true };

const items = $input.all();

const isEmpty = JSON.stringify(items[0].json) === "{}"

if (!isEmpty)
{
for (const item of $input.all()) {
  const futureDate = new Date(item.json.updated_at);
  futureDate.setMinutes(futureDate.getMinutes() + 2);
  const now = new Date();
  console.log("NOW:" + now.toISOString() +" Future:"+futureDate.toISOString())
  if (now <= futureDate)
  {
    returnValue =  { data: false };
    return returnValue; 
  }

}
}
return returnValue;

const leads = $('AggregateLeads').first().json.CustomerLeads.map(c => ({ json: { c } }));
if (leads.length > 1)
  return [];
else 
{
  const newLead = leads.filter((c)=>c.json.c.processed === false);
  // Check if newLead has any items
  if (newLead.length === 0) {
    return []; // Return empty array if no unprocessed leads
  }

  const agentFix = newLead[0].json.c;
  if (agentFix.agent.includes('Lorraine'))
  {
    const random = Math.random() < 0.5 ? 0 : 1;
    if (random === 0)
    {
      agentFix.agent = 'Lorraine'
    }
    else
    {
      agentFix.agent = 'Shimoy'
    }
  }
  return newLead;

}

const items = $input.all();

return items.map(item => {
  const phoneNumber = item.json.phoneNumber;
  const picture = item.json.fbig;

  const platform = phoneNumber ? "whatsapp" : picture?.includes("cdninstagram") ? "instagram" : picture?.includes("fbsbx") ? "facebook" : "unknown";

  return { json: { ...item.json, platform } };
});

